arguments.command:
for b in rachel monica phoebe joey chandler ross; do echo "===== $b ====="; git log --format='COMMIT %H%n%ci' --reverse origin/friend/$b | awk '
/^COMMIT /{sha=$2; getline; ts=$0; msg=""; next}
/^$/ { if (msg ~ /Friend-Message: 1/) { if (msg ~ /S06\/E20/) print sha, ts, msg } ; msg=""; next}
{ msg=msg " " $0}
END { if (msg ~ /Friend-Message: 1/ && msg ~ /S06\/E20/) print sha, ts, msg}
'; done
